&lt;h3&gt;&lt;span style=&quot;color: rgb(0, 53, 142);&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;Your skills and experience&lt;/span&gt; &lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/h3&gt;
